export function deployTemplate(
	templateId: string,
	assetIds?: string[],
	targetId?: string,
	version?: number,
	parameters?: Record<string, unknown>,
	videoIds?: string[],
): Promise<Deployment> {
	const payload: Record<string, unknown> = {
		asset_ids: assetIds ?? [],
		target_id: targetId,
		version,
		parameters,
	};
	if (videoIds !== undefined) {
		payload.video_ids = videoIds;
	}
	return request<Deployment>(
		"POST",
		`/pipeline-runs/template/${templateId}`,
		payload,
	);
}

export function batchDeployTemplate(
	templateId: string,
	assetIds: string[],
	targetId?: string,
	version?: number,
	parameters?: Record<string, unknown>,
	videoIds?: string[],
): Promise<BatchDeployResult> {
	const payload: Record<string, unknown> = {
		asset_ids: assetIds,
		target_id: targetId,
		version,
		parameters,
	};
	if (videoIds !== undefined) {
		payload.video_ids = videoIds;
	}
	return request<BatchDeployResult>(
		"POST",
		`/pipeline-runs/template/${templateId}/batch`,
		payload,
	);
}

