export function listPipelineRunSummaries(
	params?: PipelineRunListParams,
): Promise<PipelineRunListResponse> {
	const search = new URLSearchParams();
	if (params?.limit) search.set("limit", String(params.limit));
	if (params?.offset) search.set("offset", String(params.offset));
	if (params?.status) search.set("status", params.status);
	if (params?.name) search.set("name", params.name);
	if (params?.createdAfter) search.set("createdAfter", params.createdAfter);
	if (params?.finishedBefore) {
		search.set("finishedBefore", params.finishedBefore);
	}
	const suffix = search.toString() ? `?${search.toString()}` : "";
	return request<PipelineRunListResponse>("GET", `/pipeline-runs${suffix}`);
}

